import { useState } from 'react';
import type { FormEvent } from 'react';
import {
  JxStepper,
  JxButton,
  JxInputField,
  JxSelect,
  JxDivider,
} from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

const emptyValues: SignupValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(emptyValues);
  const [showErrors, setShowErrors] = useState(false);

  const setField = <K extends keyof SignupValues>(key: K, value: SignupValues[K]) => {
    setValues((prev) => ({ ...prev, [key]: value }));
  };

  const errors: Partial<Record<keyof SignupValues, string>> = {};
  if (!values.name.trim()) errors.name = 'Укажите имя';
  if (!values.email.trim()) errors.email = 'Укажите почту';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) errors.email = 'Проверьте формат почты';
  if (!values.country) errors.country = 'Выберите страну';
  if (!values.city.trim()) errors.city = 'Укажите город';
  if (!values.street.trim()) errors.street = 'Укажите улицу и дом';

  const stepFields: (keyof SignupValues)[][] = [
    ['name', 'email', 'phone'],
    ['country', 'city', 'street', 'zip'],
    [],
  ];

  const stepIsValid = stepFields[step].every((field) => !errors[field]);
  const errorOf = (field: keyof SignupValues) => (showErrors ? errors[field] : undefined);

  const goBack = () => {
    setShowErrors(false);
    setStep((prev) => Math.max(prev - 1, 0));
  };

  const goNext = () => {
    if (!stepIsValid) {
      setShowErrors(true);
      return;
    }
    setShowErrors(false);
    setStep((prev) => Math.min(prev + 1, steps.length - 1));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (step < steps.length - 1) {
      goNext();
      return;
    }
    if (Object.keys(errors).length > 0) {
      setShowErrors(true);
      setStep(errors.name || errors.email ? 0 : 1);
      return;
    }
    onSubmit(values);
  };

  const countryLabel = countries.find((item) => item.value === values.country)?.label ?? '—';

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '520px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
        {step === 0 && (
          <>
            <JxInputField
              label="Имя"
              required
              value={values.name}
              onChange={(event) => setField('name', event.target.value)}
              errorText={errorOf('name')}
            />
            <JxInputField
              label="Электронная почта"
              type="email"
              required
              value={values.email}
              onChange={(event) => setField('email', event.target.value)}
              errorText={errorOf('email')}
            />
            <JxInputField
              label="Телефон"
              type="tel"
              prefix="+7"
              placeholder="900 000-00-00"
              value={values.phone}
              onChange={(event) => setField('phone', event.target.value)}
              helperText="Необязательно"
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxSelect
              label="Страна"
              placeholder="Выберите страну"
              options={countries}
              value={values.country}
              onValueChange={(value) => setField('country', value)}
            />
            {errorOf('country') && (
              <span style={{ color: 'var(--jx-danger)', fontSize: '13px' }}>{errorOf('country')}</span>
            )}
            <JxInputField
              label="Город"
              required
              value={values.city}
              onChange={(event) => setField('city', event.target.value)}
              errorText={errorOf('city')}
            />
            <JxInputField
              label="Улица и дом"
              required
              value={values.street}
              onChange={(event) => setField('street', event.target.value)}
              errorText={errorOf('street')}
            />
            <JxInputField
              label="Индекс"
              inputMode="numeric"
              value={values.zip}
              onChange={(event) => setField('zip', event.target.value)}
              helperText="Необязательно"
            />
          </>
        )}

        {step === 2 && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            <JxDivider label="Контакты" />
            <div style={{ display: 'grid', gridTemplateColumns: '140px 1fr', gap: '8px 16px' }}>
              <span style={{ color: 'var(--jx-text-2)' }}>Имя</span>
              <span>{values.name}</span>
              <span style={{ color: 'var(--jx-text-2)' }}>Почта</span>
              <span>{values.email}</span>
              <span style={{ color: 'var(--jx-text-2)' }}>Телефон</span>
              <span>{values.phone ? `+7 ${values.phone}` : '—'}</span>
            </div>
            <JxDivider label="Адрес" />
            <div style={{ display: 'grid', gridTemplateColumns: '140px 1fr', gap: '8px 16px' }}>
              <span style={{ color: 'var(--jx-text-2)' }}>Страна</span>
              <span>{countryLabel}</span>
              <span style={{ color: 'var(--jx-text-2)' }}>Город</span>
              <span>{values.city}</span>
              <span style={{ color: 'var(--jx-text-2)' }}>Улица и дом</span>
              <span>{values.street}</span>
              <span style={{ color: 'var(--jx-text-2)' }}>Индекс</span>
              <span>{values.zip || '—'}</span>
            </div>
          </div>
        )}
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step === steps.length - 1 ? (
          <JxButton variant="primary" type="submit">
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" type="button" onClick={goNext}>
            Дальше
          </JxButton>
        )}
      </div>
    </form>
  );
}

